const QA = [
  { type: 'placeholders', label: 'Placeholders', tr: true, skipHtml: false },
  { type: 'html', label: 'HTML', tr: true, skipHtml: false },
  { type: 'inline_code', label: 'Missing inline code', tr: true, skipHtml: false },
  // REMOVED 2026-08-28 (Mary): unbalanced_brackets. Our ()[]{} balance scan could only
  // attribute ~60% of what Lokalise flags - 33 of 39 unattributed on Personality Members
  // area - so the locale column could not be trusted. Handler + emoticon guard remain in
  // Build Slack Report; re-enable only once the bracket forms Lokalise counts are known.
  // { type: 'unbalanced_brackets', label: 'Unbalanced brackets', tr: true, skipHtml: false },
  // ON HOLD 2026-08-28: leading_whitespace + trailing_whitespace with include_translations
  // pushed the run past its 900s timeout (execution 562882 cancelled at 15 min).
  // Build Slack Report still handles both labels correctly - re-enable by uncommenting
  // here AND adding them back to LABELS, once the payload cost is solved.
  // { type: 'leading_whitespace', label: 'Leading whitespace', tr: true, skipHtml: false },
  // { type: 'trailing_whitespace', label: 'Trailing whitespace', tr: true, skipHtml: false },
  { type: 'double_space', label: 'Double space', tr: true, skipHtml: true }
];

function isHtmlProject(name) {
  const s = (name || '').toLowerCase();
  return s.indexOf('html') >= 0 || s.indexOf('legal page') >= 0;
}

const out = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    const base = (p.base_language_iso || 'en').toLowerCase();
    const htmlProject = isHtmlProject(p.name);
    for (const q of QA) {
      if (q.skipHtml && htmlProject) { continue; }
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: base,
        qa_type: q.type,
        qa_label: q.label,
        extra: q.tr ? '&include_translations=1' : ''
      }});
    }
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: base,
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__',
        extra: ''
      }});
      first = false;
    }
  }
}
return out;

// Only list checks that actually RAN. A label left here while its request is
// commented out of Build QA Requests prints "0", which reads as "nothing wrong"
// when it means "we did not look". Keep this in step with the QA array.
const LABELS = ['Placeholders', 'HTML', 'Missing inline code', 'Double space (translations)'];
const reqs = $('Build QA Requests').all();
const res = $input.all();
const rows = {};
const projIds = {};
const order = [];
const failed = [];
const truncated = [];
let controlStatus = null;
let inheritedSkipped = 0;
let htmlProjectsSkipped = 0;
let pseudoOnlySkipped = 0;
let frenchSpacingSkipped = 0;
let supOnlySkipped = 0;

// Baseline of previously-flagged key ids, held in workflow static data.
// n8n persists static data ONLY after production (scheduled) executions, so a manual
// run reads the baseline but never overwrites it. That is exactly what we want:
// "new" means new since the last AUTOMATIC 02:00 report, not since someone last
// clicked Execute. Nothing to configure - the behaviour falls out of n8n's semantics.
const store = $getWorkflowStaticData('global');
const prev = (store.qaBaseline && typeof store.qaBaseline === 'object') ? store.qaBaseline : null;
const baseStamp = store.qaBaselineAt || null;
const hasBaseline = !!prev;
const baseMap = {};
if (prev) {
  for (const scope in prev) {
    const set = {};
    for (const id of (prev[scope] || [])) { set[String(id)] = 1; }
    baseMap[scope] = set;
  }
}
const nextBaseline = {};
const nowIso = new Date().toISOString();

// Pseudo-translation is never scanned or blamed - its strings are machine-mangled.
// NOTE: 'ps' is also the real ISO code for Pashto. It is treated as pseudo here by
// explicit instruction; narrow this list if Pashto is ever a real target language.
const PSEUDO = { 'pst': 1, 'ps': 1, 'ps_ps': 1, 'ps-ps': 1, 'xx': 1, 'zz': 1, 'qps': 1 };
function isPseudo(iso) {
  const s = (iso || '').toLowerCase().trim();
  if (PSEUDO[s]) { return true; }
  return s.indexOf('pseudo') >= 0 || s.indexOf('_ps') >= 0 || s.indexOf('-ps') >= 0;
}

// Placeholder styles: %1$s, %s/%d/%@, %NAME%, {{x}}, {x}, [VAR], [[VAR]].
// ":name" is deliberately NOT matched - it collides with ordinary punctuation.
const PH = /%\d+\$[a-zA-Z]|%[sdfi@]|%[A-Za-z_][A-Za-z0-9_]*%|\{\{[^{}]+\}\}|\{[^{}]*\}|\[\[[A-Za-z0-9_.-]+\]\]|\[[A-Za-z0-9_.-]+\]/g;
const TAG = /<\/?([a-zA-Z][a-zA-Z0-9]*)\b[^>]*>/g;
// <sup> is excluded from the HTML comparison: English ordinals (1<sup>st</sup>),
// footnote and trademark markers have no equivalent in most languages, so a target
// legitimately differs. <sub> is NOT excluded - chemical and maths notation should match.
const HTML_IGNORE = { 'sup': 1 };
// Inline code: markdown backtick spans and <code> elements. Contents are compared,
// not just the count - a translated identifier is as broken as a dropped one.
const CODE = /`[^`\n]*`|<code\b[^>]*>[\s\S]*?<\/code>/g;

// French spacing: a space belongs before ; : ! ? % and inside guillemets. When that
// space is an NBSP next to an ordinary one it looks like a double space to the checker,
// so strip the legitimate spacing before testing. fr-CA/fr-BE/fr-CH included.
const FR = /^fr([-_]|$)/;
const SP = '[ \\u00a0\\u202f\\u2009\\u2007\\u2008]';
const FR_BEFORE = new RegExp(SP + '+(?=[;:!?%\\u00bb\\u20ac])', 'g');
const FR_AFTER = new RegExp('\\u00ab' + SP + '+', 'g');
function stripFrenchSpacing(v) {
  return v.replace(FR_BEFORE, '').replace(FR_AFTER, '«');
}

// Leading / trailing whitespace. JS \s already covers NBSP, narrow NBSP and the
// U+2000-200a run, so no separate class is needed.
function edgeWs(str, lead) {
  if (!str) { return false; }
  return lead ? /^\s/.test(str) : /\s$/.test(str);
}

// Emoticons are brackets used as faces, not as brackets. EN copy uses them and
// translators carry them across; counting them as unbalanced is pure noise.
const EMOTICON = /[:;=8xX][-~^'°]?[)(\]\[}{|DPpoO3><]+|[)(\]\[}{][-~^']?[:;=8]/g;

// Unbalanced brackets is a target-only defect - nothing to compare against the source.
// The SOURCE is never judged: if EN is unbalanced the key is dropped as inherited.
function bracketsUnbalanced(str) {
  str = String(str).replace(EMOTICON, '');
  const CLOSE = { ')': '(', ']': '[', '}': '{' };
  const OPEN = { '(': 1, '[': 1, '{': 1 };
  const st = [];
  for (let i = 0; i < str.length; i++) {
    const ch = str.charAt(i);
    if (OPEN[ch]) { st.push(ch); }
    else if (CLOSE[ch]) {
      if (st.length === 0 || st[st.length - 1] !== CLOSE[ch]) { return true; }
      st.pop();
    }
  }
  return st.length > 0;
}

function inv(str, re, byName, ignore) {
  const m = {};
  let x;
  re.lastIndex = 0;
  while ((x = re.exec(str)) !== null) {
    const t = byName ? x[1].toLowerCase() : x[0];
    if (ignore && ignore[t]) { continue; }
    m[t] = (m[t] || 0) + 1;
  }
  return m;
}

function differs(a, b) {
  const ks = {};
  for (const k in a) { ks[k] = 1; }
  for (const k in b) { ks[k] = 1; }
  for (const k in ks) { if ((a[k] || 0) !== (b[k] || 0)) { return true; } }
  return false;
}

// Which target locales differ from the source for this check.
// Returns [] when there is no source text or nothing to compare - those keys
// are counted in the total but reported as unattributed.
function localesForKey(k, baseLang, kind) {
  let src = null;
  const tgts = [];
  for (const tr of (k.translations || [])) {
    const v = (typeof tr.translation === 'string') ? tr.translation : '';
    const iso = (tr.language_iso || '').toLowerCase();
    if (iso === baseLang) { src = v; }
    else { tgts.push({ iso: iso, v: v, pseudo: isPseudo(iso) }); }
  }
  const out = { real: [], pseudo: 0, supOnly: 0 };
  if (src === null) { return out; }
  const byName = (kind === 'HTML');
  let re = PH;
  if (byName) { re = TAG; }
  else if (kind === 'Missing inline code') { re = CODE; }
  // Two inventories for HTML: one ignoring <sup>, one counting everything. A target
  // that differs only once <sup> is put back is a legitimate ordinal/marker
  // difference, not a defect - reported as supOnly so the key can be dropped.
  const ignore = byName ? HTML_IGNORE : null;
  const siReal = inv(src, re, byName, ignore);
  const siFull = ignore ? inv(src, re, byName, null) : siReal;
  for (const t of tgts) {
    if (!t.v || !t.v.trim()) { continue; }
    const tReal = inv(t.v, re, byName, ignore);
    if (differs(siReal, tReal)) {
      if (t.pseudo) { out.pseudo++; } else { out.real.push(t.iso); }
      continue;
    }
    if (!ignore || t.pseudo) { continue; }
    if (differs(siFull, inv(t.v, re, byName, null))) { out.supOnly++; }
  }
  return out;
}

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;

  const r = res[i].json || {};
  const hdr = r.headers || {};

  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name + ' / ' + meta.qa_label); }

  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  if (total !== null && total > keys.length) { truncated.push(meta.project_name + ' / ' + meta.qa_label); }

  if (!rows[meta.project_name]) { rows[meta.project_name] = {}; order.push(meta.project_name); }
  projIds[meta.project_name] = meta.project_id;

  const loc = {};
  const ids = [];
  let count = 0;
  let unattr = 0;

  if (meta.qa_label === 'Double space') {
    for (const k of keys) {
      if (k.is_archived) { continue; }
      let srcHas = false;
      const hits = [];
      let pseudoHit = false;
      for (const tr of (k.translations || [])) {
        const v = tr.translation;
        if (typeof v !== 'string') { continue; }
        const iso = (tr.language_iso || '').toLowerCase();
        let text = v;
        if (FR.test(iso)) { text = stripFrenchSpacing(v); }
        if (!/ {2,}/.test(text)) {
          if (FR.test(iso) && / {2,}/.test(v)) { frenchSpacingSkipped++; }
          continue;
        }
        if (iso === meta.base_lang) { srcHas = true; }
        else if (isPseudo(iso)) { pseudoHit = true; }
        else { hits.push(iso); }
      }
      if (srcHas) { if (hits.length > 0) { inheritedSkipped++; } continue; }
      if (hits.length === 0) { if (pseudoHit) { pseudoOnlySkipped++; } continue; }
      count++;
      ids.push(k.key_id);
      for (const iso of hits) { loc[iso] = (loc[iso] || 0) + 1; }
    }
    rows[meta.project_name]['Double space (translations)'] =
      (total === null) ? null : { n: count, loc: loc, unattr: 0, ids: ids };
  } else if (meta.qa_label === 'Leading whitespace' || meta.qa_label === 'Trailing whitespace') {
    // Only blame a target when the SOURCE does not have the same edge whitespace.
    // Source-side padding is deliberate concatenation spacing or a repo artefact:
    // either way the translator did not introduce it and cannot keep it fixed.
    const lead = (meta.qa_label === 'Leading whitespace');
    for (const k of keys) {
      if (k.is_archived) { continue; }
      let src = null;
      const hits = [];
      let pseudoHit = false;
      for (const tr of (k.translations || [])) {
        const v = (typeof tr.translation === 'string') ? tr.translation : '';
        const iso = (tr.language_iso || '').toLowerCase();
        if (iso === meta.base_lang) { src = v; continue; }
        if (!v.trim()) { continue; }
        if (!edgeWs(v, lead)) { continue; }
        if (isPseudo(iso)) { pseudoHit = true; } else { hits.push(iso); }
      }
      if (src !== null && edgeWs(src, lead)) {
        if (hits.length > 0) { inheritedSkipped++; }
        continue;
      }
      if (hits.length === 0) {
        if (pseudoHit) { pseudoOnlySkipped++; continue; }
        count++;
        ids.push(k.key_id);
        unattr++;
        continue;
      }
      count++;
      ids.push(k.key_id);
      for (const iso of hits) { loc[iso] = (loc[iso] || 0) + 1; }
    }
    rows[meta.project_name][meta.qa_label] =
      (total === null) ? null : { n: count, loc: loc, unattr: unattr, ids: ids };
  } else if (meta.qa_label === 'Unbalanced brackets') {
    for (const k of keys) {
      if (k.is_archived) { continue; }
      let src = null;
      const hits = [];
      let pseudoHit = false;
      for (const tr of (k.translations || [])) {
        const v = (typeof tr.translation === 'string') ? tr.translation : '';
        const iso = (tr.language_iso || '').toLowerCase();
        if (iso === meta.base_lang) { src = v; continue; }
        if (!v.trim()) { continue; }
        if (!bracketsUnbalanced(v)) { continue; }
        if (isPseudo(iso)) { pseudoHit = true; } else { hits.push(iso); }
      }
      if (src !== null && bracketsUnbalanced(src)) {
        if (hits.length > 0) { inheritedSkipped++; }
        continue;
      }
      if (hits.length === 0) {
        if (pseudoHit) { pseudoOnlySkipped++; continue; }
        count++;
        ids.push(k.key_id);
        unattr++;
        continue;
      }
      count++;
      ids.push(k.key_id);
      for (const iso of hits) { loc[iso] = (loc[iso] || 0) + 1; }
    }
    rows[meta.project_name]['Unbalanced brackets'] =
      (total === null) ? null : { n: count, loc: loc, unattr: unattr, ids: ids };
  } else {
    for (const k of keys) {
      if (k.is_archived) { continue; }
      const ls = localesForKey(k, meta.base_lang, meta.qa_label);
      if (ls.real.length === 0 && ls.pseudo > 0) { pseudoOnlySkipped++; continue; }
      // Only difference anywhere was <sup>: drop the key rather than report it as
      // unattributed, which would leave a number nobody should act on.
      if (ls.real.length === 0 && ls.supOnly > 0) { supOnlySkipped++; continue; }
      count++;
      ids.push(k.key_id);
      if (ls.real.length === 0) { unattr++; continue; }
      for (const iso of ls.real) { loc[iso] = (loc[iso] || 0) + 1; }
    }
    rows[meta.project_name][meta.qa_label] =
      (total === null) ? null : { n: count, loc: loc, unattr: unattr, ids: ids };
  }

  // Diff against the baseline, and stage this scope's ids to become the next baseline.
  // A scope whose request FAILED is skipped entirely so a good baseline is never
  // overwritten with an empty one.
  if (total !== null) {
    const scope = meta.project_id + '::' + meta.qa_label;
    const cell = rows[meta.project_name][meta.qa_label] ||
                 rows[meta.project_name]['Double space (translations)'];
    const base = baseMap[scope];
    if (cell) {
      if (!base) {
        cell.newCount = null;
      } else {
        let n = 0;
        for (const id of ids) { if (!base[String(id)]) { n++; } }
        cell.newCount = n;
      }
    }
    nextBaseline[scope] = ids;
  }
}

for (const name of order) {
  const s = name.toLowerCase();
  if (s.indexOf('html') >= 0 || s.indexOf('legal page') >= 0) { htmlProjectsSkipped++; }
}

const totals = {};
for (const l of LABELS) { totals[l] = 0; }
const flagged = [];
for (const name of order) {
  const r = rows[name];
  let sum = 0;
  for (const l of LABELS) {
    const c = r[l];
    if (c && typeof c.n === 'number') { sum += c.n; totals[l] += c.n; }
  }
  if (sum > 0) { flagged.push({ name: name, r: r, sum: sum }); }
}
flagged.sort(function (a, b) {
  return a.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase().localeCompare(b.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase());
});

let totalNew = 0;
for (const name of order) {
  for (const l of LABELS) {
    const c = rows[name][l];
    if (c && typeof c.newCount === 'number') { totalNew += c.newCount; }
  }
}

const MAX_LOC = 8;
function fmtLoc(c) {
  const arr = [];
  for (const iso in c.loc) { arr.push([iso, c.loc[iso]]); }
  arr.sort(function (a, b) { return (b[1] - a[1]) || a[0].localeCompare(b[0]); });
  const parts = [];
  for (let i = 0; i < arr.length && i < MAX_LOC; i++) { parts.push(arr[i][0] + ' ' + arr[i][1]); }
  if (arr.length > MAX_LOC) { parts.push('+' + (arr.length - MAX_LOC) + ' more'); }
  if (c.unattr > 0) { parts.push(c.unattr + ' unattributed'); }
  return parts.join(', ');
}

let summary = '*Lokalise integrated QA checks report* — ' + order.length + ' projects scanned\n\n';
summary += '*Totals*\n';
for (const l of LABELS) { summary += '• ' + l + ': ' + totals[l] + '\n'; }
summary += '\n';
// Celebrate ONLY a verified clean sweep. Zeros are not trustworthy if the control
// probe did not 400, if any project could not be read, or if a count was truncated -
// congratulating the team on an unverified zero would be worse than saying nothing.
const cleanSweep = (flagged.length === 0);
const verified = (controlStatus === 400 && failed.length === 0 && truncated.length === 0);
if (cleanSweep && verified) {
  summary += ':tada: :confetti_ball: *CONGRATULATIONS!* :confetti_ball: :tada:\n';
  summary += '*Every single check is clean across all ' + order.length + ' projects.*\n';
  summary += 'Placeholders, HTML, inline code and double spaces — zero issues, account-wide.\n';
  summary += 'Genuinely excellent work, everyone. :clap:\n';
} else if (cleanSweep) {
  summary += ':white_check_mark: No issues found in any project — but see the warning below before celebrating.\n';
} else {
  summary += '*' + flagged.length + ' of ' + order.length + ' projects have issues* — per-project breakdown, with locales, in thread.\n';
  summary += ':white_check_mark: ' + (order.length - flagged.length) + ' project(s) clean.\n';
}
if (!hasBaseline) {
  summary += '\n:information_source: Change tracking has no baseline yet — it is set by the scheduled 02:00 run. New issues will be flagged from the nightly after that.\n';
} else if (totalNew > 0) {
  summary += '\n:new: *' + totalNew + ' new issue' + (totalNew === 1 ? '' : 's') + '* since the last nightly report' +
    (baseStamp ? ' (' + String(baseStamp).slice(0, 16).replace('T', ' ') + ' UTC)' : '') + '.\n';
} else {
  summary += '\n:new: No new issues since the last nightly report.\n';
}
if (failed.length > 0) { summary += '\n:warning: could not read: ' + failed.join(', '); }
if (truncated.length > 0) { summary += '\n:warning: over 500 flagged keys, count is a floor: ' + truncated.join(', '); }
if (controlStatus !== 400) { summary += '\n:rotating_light: control probe returned ' + controlStatus + ' instead of 400 — the QA filter may not be applied, treat these numbers as unverified.'; }

// Slack Block Kit payload. A section carries the text; on a verified clean sweep an
// image block carries the gif. An image block RENDERS the gif - posting the bare URL
// and hoping Slack unfurls it does not, which is what happened the first time.
const CELEBRATION_GIF = 'https://media.giphy.com/media/g9582DNuQppxC/giphy.gif';
const blocks = [{
  type: 'section',
  text: { type: 'mrkdwn', text: summary.length > 2900 ? summary.slice(0, 2897) + '...' : summary }
}];
if (cleanSweep && verified) {
  blocks.push({ type: 'image', image_url: CELEBRATION_GIF, alt_text: 'Celebration - every QA check is clean' });
}
const summaryBlocks = JSON.stringify({ blocks: blocks });

const BASE = 'https://app.lokalise.com/project/';
function link(name) {
  const id = projIds[name];
  const label = String(name).replace(/[<>|]/g, ' ').trim();
  if (!id) { return '*' + label + '*'; }
  return '<' + BASE + id + '/|' + label + '>';
}

function isHtmlProject(name) {
  const s = (name || '').toLowerCase();
  return s.indexOf('html') >= 0 || s.indexOf('legal page') >= 0;
}

function blockFor(f) {
  let block = link(f.name);
  for (const l of LABELS) {
    const c = f.r[l];
    if (!c || typeof c.n !== 'number' || c.n === 0) { continue; }
    const ls = fmtLoc(c);
    const isNew = (typeof c.newCount === 'number' && c.newCount > 0)
      ? '   :new: ' + c.newCount + ' new'
      : '';
    block += '\n    • ' + l + ': ' + c.n + ' keys' + (ls ? '  —  ' + ls : '') + isNew;
  }
  return block;
}

// Product projects first, html/legal-pages projects after a divider. Their defects
// are a different job for a different person, and mixing them buries the app strings.
const lines = [];
const htmlLines = [];
for (const f of flagged) {
  if (isHtmlProject(f.name)) { htmlLines.push(blockFor(f)); }
  else { lines.push(blockFor(f)); }
}
const DIVIDER = '————————————————————\n*html / legal pages projects*';
if (htmlLines.length > 0) {
  if (lines.length === 0) { lines.push('_No issues outside html / legal pages._'); }
  lines.push(DIVIDER);
  for (const hl of htmlLines) { lines.push(hl); }
}

const LIMIT = 3500;
const HEAD_ROOM = 90;
const BUDGET = LIMIT - HEAD_ROOM;
const SEP = 2;

const safeLines = [];
for (const ln of lines) {
  safeLines.push(ln.length <= BUDGET ? ln : ln.slice(0, BUDGET - 2) + '…');
}

function groupBy(target) {
  const gs = [];
  let g = [];
  let gLen = 0;
  for (const ln of safeLines) {
    const add = ln.length + SEP;
    if (gLen > 0 && (gLen + add > target || gLen + add > BUDGET)) {
      gs.push(g);
      g = [];
      gLen = 0;
    }
    g.push(ln);
    gLen += add;
  }
  if (g.length > 0) { gs.push(g); }
  return gs;
}

const minChunks = groupBy(BUDGET).length;
let lo = 1;
for (const ln of safeLines) { if (ln.length + SEP > lo) { lo = ln.length + SEP; } }
let hi = BUDGET;
let best = BUDGET;
while (lo <= hi) {
  const mid = Math.floor((lo + hi) / 2);
  if (groupBy(mid).length <= minChunks) { best = mid; hi = mid - 1; }
  else { lo = mid + 1; }
}
const groups = groupBy(best);

const chunks = [];
for (let gi = 0; gi < groups.length; gi++) {
  const head = (gi === 0)
    ? '*Projects with issues*\n\n'
    : '*Projects with issues (cont. ' + (gi + 1) + ' of ' + groups.length + ')*\n\n';
  chunks.push(head + groups[gi].join('\n\n') + '\n');
}

// Persist for the next run. Guarded: if the account ever balloons past this many
// flagged keys, stop storing rather than bloat the workflow's static data - the
// report still works, it just cannot flag new issues until the backlog comes down.
let totalIds = 0;
