  // A scope whose request FAILED is skipped entirely so a good baseline is never
  // overwritten with an empty one.
  if (total !== null) {
    const scope = meta.project_id + '::' + meta.qa_label;
    const cell = rows[meta.project_name][meta.qa_label] ||
                 rows[meta.project_name]['Double space (translations)'];
    const base = baseMap[scope];
    if (cell) {
      if (!base) {
        cell.newCount = null;
      } else {
        let n = 0;
        for (const id of ids) { if (!base[String(id)]) { n++; } }
        cell.newCount = n;
      }
    }
    nextBaseline[scope] = ids;
  }
}

for (const name of order) {
