const SEP = 2;

const safeLines = [];
for (const ln of lines) {
  safeLines.push(ln.length <= BUDGET ? ln : ln.slice(0, BUDGET - 2) + '…');
}

function groupBy(target) {
  const gs = [];
  let g = [];
  let gLen = 0;
  for (const ln of safeLines) {
    const add = ln.length + SEP;
    if (gLen > 0 && (gLen + add > target || gLen + add > BUDGET)) {
      gs.push(g);
      g = [];
      gLen = 0;
    }
    g.push(ln);
    gLen += add;
  }
  if (g.length > 0) { gs.push(g); }
  return gs;
}

const minChunks = groupBy(BUDGET).length;
let lo = 1;
for (const ln of safeLines) { if (ln.length + SEP > lo) { lo = ln.length + SEP; } }
let hi = BUDGET;
let best = BUDGET;
while (lo <= hi) {
  const mid = Math.floor((lo + hi) / 2);
  if (groupBy(mid).length <= minChunks) { best = mid; hi = mid - 1; }
  else { lo = mid + 1; }
}
const groups = groupBy(best);

const chunks = [];
for (let gi = 0; gi < groups.length; gi++) {
  const head = (gi === 0)
    ? '*Projects with issues*\n\n'
    : '*Projects with issues (cont. ' + (gi + 1) + ' of ' + groups.length + ')*\n\n';
  chunks.push(head + groups[gi].join('\n\n') + '\n');
}

// Persist for the next run. Guarded: if the account ever balloons past this many
// flagged keys, stop storing rather than bloat the workflow's static data - the
// report still works, it just cannot flag new issues until the backlog comes down.
let totalIds = 0;
for (const k in nextBaseline) { totalIds += nextBaseline[k].length; }
let baselineSaved = false;
if (totalIds <= 20000) {
  store.qaBaseline = nextBaseline;
  store.qaBaselineAt = nowIso;
  baselineSaved = true;
} else {
  store.qaBaselineTooLarge = totalIds;
}

return [{ json: {
  summary: summary,
  summary_blocks: summaryBlocks,
  celebrated: (cleanSweep && verified),
  chunks: chunks,
  chunk_count: chunks.length,
  total_new: totalNew,
  has_baseline: hasBaseline,
  baseline_stamp: baseStamp,
  baseline_scopes: Object.keys(nextBaseline).length,
  baseline_key_count: totalIds,
  baseline_saved: baselineSaved,
  project_count: order.length,
  flagged_count: flagged.length,
  totals: totals,
  failures: failed.length,
  truncated: truncated.length,
  control_status: controlStatus,
  inherited_from_source_skipped: inheritedSkipped,
  html_projects_excluded_from_double_space: htmlProjectsSkipped,
  pseudo_only_keys_skipped: pseudoOnlySkipped,
  french_punctuation_spacing_skipped: frenchSpacingSkipped,
  sup_only_html_keys_skipped: supOnlySkipped
}}];

const built = $('Build Slack Report').first().json;
const posted = $('Post Summary').first().json;
const ts = posted.ts || (posted.message && posted.message.ts) || null;
const out = [];
for (const c of (built.chunks || [])) {
  out.push({ json: { text: c, thread_ts: ts } });
}
return out;
